// ListDefinitionOptionsByDefinitionIDs runs the :many query against sqlite.
func (q *sqliteQueries) ListDefinitionOptionsByDefinitionIDs(ctx context.Context, db DBTX, arg ListDefinitionOptionsByDefinitionIDsParams) ([]ListDefinitionOptionsByDefinitionIDsRow, error) {
	query := q.listDefinitionOptionsByDefinitionIDs

	args := make([]any, 0, len(arg.IDs))

	query = strings.Replace(query, "/*SLICE:ids*/?", slicePlaceholders("?", len(arg.IDs)), 1)

	for _, v := range arg.IDs {
		args = append(args, v)
	}

	rows, err := db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, err
	}

	defer func() { _ = rows.Close() }()

	var items []ListDefinitionOptionsByDefinitionIDsRow

	for rows.Next() {
		var i ListDefinitionOptionsByDefinitionIDsRow

		if err := rows.Scan(
			&i.DefinitionID,
			&i.Value,
		); err != nil {
			return nil, err
		}

		items = append(items, i)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return items, nil
}

